INSERT INTO `casestudy` (`id`, `title`, `description`, `short_description`, `long_description`, `image`, `og_image`, `banner_image`, `meta_title`, `meta_description`, `alt`, `alt_banner`, `url`, `is_delete`, `created_at`, `updated_at`) VALUES
(1, 'sadfdfgioi;ooiuytryui', '<p>sadfgfdghj</p>', 'Restore your smile with confidence: Discover how dental crowns and bridges can reconstruct damaged teeth, increase your appearance,', '<p>efdg</p>', 'image_1757590473.png', 'og_image_1757590473.png', 'banner_1757590473.png', 'anti-microbial-wound-filter-cartridge', 'Polypropylene Yarn', '4retertyiu', NULL, 'dfgfdtygij', 1, '2025-09-11 11:34:33', '2025-09-11 06:05:05'),
(2, 'Resilience in the Face of Tariffs – mmp Filtration Pvt Ltd', '<p><b>Background:</b> In August 2025, the U.S. government imposed a steep 50% additional tariff on imports of filtration materials. This posed a significant challenge for exporters worldwide, especially those supplying specialized products such as PP Filtration Yarn</p>\r\n                \r\n                <h3 class=\"f_24\">The Challenge: </h3>\r\n                <p>\r\n                    For <b> mmp Filtration Pvt Ltd,</b> this sudden tariff threatened competitiveness in one of its key markets, the United States. Customers faced higher landed costs, making supplier retention difficult in an environment where price often dominates purchasing decisions.\r\n                </p>', 'When a sudden 50% U.S. tariff hit filtration imports, <strong>mmp</strong> Filtration Pvt Ltd retained a customer—not by lowering prices, but through consistent quality and reliable deliveries.', '<h3 class=\"f_24\">The Breakthrough :</h3>\r\n                <p>\r\n                    Despite these circumstances, a reputed U.S. customer, a 125-year-old company with a long-standing market presence, chose to place a large order with <strong>mmp</strong> Filtration Pvt Ltd. The decision was not based on pricing but on two critical factors:\r\n                </p>\r\n                 <h3 class=\"f_24\">The Outcome :</h3>\r\n                <p>\r\n                    Despite these circumstances, a reputed U.S. customer, a 125-year-old company with a long-standing market presence, chose to place a large order with <strong>mmp</strong> Filtration Pvt Ltd. The decision was not based on pricing but on two critical factors:\r\n                </p>\r\n                <h3 class=\"f_24\">Key Takeaway :</h3>\r\n                <p>\r\n                    Even in the face of external pressures like tariffs, customer loyalty can be earned and sustained when a company delivers unmatched quality, reliability, and trust. For <strong>mmp</strong> Filtration Pvt Ltd, this moment serves as both recognition of past efforts and motivation to continue striving for excellence in the global market.\r\n                </p>', 'image_1757598689.jpg', 'og_image_1757598689.jpg', 'banner_1757598689.jpg', 'Resilience in the Face of Tariffs', 'Discover how mmp Filtration overcame a 50% US tariff by delivering consistent quality & on-time deliveries, earning trust from a 125-year-old American customer.', 'Resilience in the Face of Tariffs – mmp Filtration Pvt Ltd', NULL, 'resilience-in-the-face-of-tariffs', 0, '2025-09-11 11:59:07', NULL),
(3, 'Transforming RO Plant Performance with PPH Housing', '<p><b>Background:</b> An established company in the <strong>RO Treatment industry</strong>\r\n     specializes in manufacturing filtration plants using traditional <strong>SS housings.</strong> While stainless steel was the\r\n      standard, the company repeatedly faced challenges such as <strong>leakages, durability concerns, and inconsistent quality.</strong> \r\n      These issues not only increased operational costs but also disrupted their efficiency. </p>\r\n                \r\n                <h3 class=\"f_24\">The Challenge: </h3>\r\n                <p>\r\n                   Frequent maintenance and repairs due to SS housing failures forced the company to look for alternatives. \r\n                   The need was clear: a <strong>sturdy, reliable, and cost-efficient filtration housing solution</strong> that could perform \r\n                   consistently in demanding applications.\r\n                </p>', 'An RO treatment company struggling with SS housings switched to mmp’s PPH Housing, eliminating leaks, cutting costs, and achieving long-term reliability for future projects.', '<h3 class=\"f_24\">The Solution:</h3> \r\n<p>The company then decided to trial <strong>mmp Filtration Pvt Ltd’s PPH Housing – 7x32” bag filter housing.</strong> This product was designed to overcome the limitations of traditional SS housings by offering superior sturdiness, chemical resistance, and long-term reliability.</p>\r\n\r\n<h3 class=\"f_24\">The Result:</h3> \r\n<p>After trials, the feedback was overwhelmingly positive:</p>\r\n\r\n<ul style=\"    list-style: disc;\r\n \">\r\n<li>“The quality of PPH housing is excellent.”</li>\r\n\r\n<li>“We no longer need to budget for housing-related expenses; only the bag filters require replacement.”</li>\r\n\r\n<li>“The sturdiness is exemplary compared to the SS housings we used earlier.”</li>\r\n</ul>\r\n\r\n<p>The company confirmed that switching to <strong>mmp’s</strong> PPH Housing <strong>eliminated leakage problems, reduced maintenance costs, and enhanced reliability</strong>, making it a preferred choice for future projects.</p>\r\n\r\n\r\n<h3 class=\"f_24\">Key Takeaway:</h3> \r\n<p>This experience highlights how <strong>mmp Filtration Pvt Ltd’s innovation in PPH housings</strong> is reshaping industry standards.\r\n     By providing <strong>durability, cost savings, and reliability, mmp</strong> continues to earn strong recommendations from industry players who seek long-term, trouble-free solutions.</p>', 'image_1757598717.jpg', 'og_image_1757598717.jpg', 'banner_1757598717.jpg', 'Transforming RO Plant Performance with PPH Housing', 'Learn how an RO Treatment company overcame SS housing issues by switching to mmp Filtration’s PPH Housing, gaining durability & long-term reliability.', 'Transforming RO Plant Performance with PPH Housing', NULL, 'transforming-ro-plant-performance', 0, '2025-09-11 13:39:25', NULL),
(4, 'Upgrading Bag Filter Housings in Steel Manufacturing', '<p><b>Background:</b> Airborne particulate removal is critical in steel manufacturing, especially from furnace exhaust systems. \r\n    Traditionally, <strong>stainless steel (SS) housings</strong> were used; however, recurring issues such as <strong>leaks, corrosion, and inconsistent \r\n    quality</strong> resulted in higher costs and frequent downtime for a leading steel producer.</p>\r\n                \r\n                <h3 class=\"f_24\">The Challenge: </h3>\r\n                <p>\r\n                   The operation team faced multiple challenges with the SS housings:\r\n                </p>\r\n\r\n                <ul style=\"list-style: disc;\">\r\n                    <li>Frequent leakages requiring intervention</li>\r\n                    <li>Corrosion damage leading to premature replacement</li>\r\n                    <li>Unplanned downtime affecting production continuity</li>\r\n                    <li>Rising costs from spares and maintenance</li>\r\n                </ul>', 'A leading steel producer eliminated leakages, corrosion, and downtime by upgrading from SS housings to mmp’s PPH Housing—achieving seamless operations and cost savings.', '<h3 class=\"f_24\">The Solution:</h3> \r\n<p>The producer upgraded to <strong>mmp Filtration Pvt Ltd’s PPH Housing 7×32”</strong>, designed to withstand any harsh operating conditions while eliminating the shortcomings of SS housings.</p>\r\n\r\n<h3 class=\"f_24\">The Result:</h3> \r\n\r\n<p></p>\r\n<table class=\"table table-bordered mb-0\">\r\n  <tbody>\r\n    <!-- Header -->\r\n    <tr>\r\n      <td style=\"color: #fff; background: #023f88; \">Performance Metric</td>\r\n      <td style=\"background: rgb(2, 63, 136);\"><p><font color=\"#ffffff\">SS Housing</font></p></td>\r\n      <td style=\"background: rgb(2, 63, 136);\"><p><font color=\"#ffffff\">PPH Housing 7×32”</font></p></td>\r\n    </tr>\r\n\r\n    <!-- Data Rows -->\r\n    <tr style=\"background: #F3F3F3;\">\r\n      <td>Leak Occurrences</td>\r\n      <td>3 in four weeks</td>\r\n      <td>0</td>\r\n    </tr>\r\n    <tr>\r\n      <td>Maintenance Interventions</td>\r\n      <td>Multiple gasket replacements</td>\r\n      <td>None</td>\r\n    </tr>\r\n    <tr style=\"background: #F3F3F3;\">\r\n      <td>Corrosion Damage</td>\r\n      <td>Visible pitting and scaling</td>\r\n      <td>None observed</td>\r\n    </tr>\r\n    <tr>\r\n      <td>Downtime Impact</td>\r\n      <td>12 hours</td>\r\n      <td>0 hours</td>\r\n    </tr>\r\n    <tr style=\"background: #F3F3F3;\">\r\n      <td>Operating Cost Overhaul</td>\r\n      <td>High spares consumption</td>\r\n      <td>Only filter bags</td>\r\n    </tr>\r\n  </tbody>\r\n</table>\r\n\r\n\r\n<h3 class=\"f_24\">Key Takeaway:</h3> \r\n<p> By adopting <strong>mmp’s PPH Housing 7×32”</strong>, the steel producer completely eliminated housing-related maintenance. \r\n    The operations team now focuses solely on bag filter replacement, resulting in <strong>reduced downtime, simplified maintenance planning,\r\n     and lower operating costs</strong> while ensuring environmental compliance.</p>', 'image_1757598739.jpg', 'og_image_1757598739.jpg', 'banner_1757598739.jpg', 'Upgrading Bag Filter Housings in Steel Manufacturing', 'Discover how a leading steel producer solved leakage, corrosion, and downtime issues by upgrading from stainless steel to mmp Filtration’s durable PPH Housing.', 'Upgrading Bag Filter Housings in Steel Manufacturing', NULL, 'upgrading-bag-filter-housings', 0, '2025-09-11 13:44:33', NULL);
